public static boolean isValidUTF8(ByteBuffer data, int off) {
  int len = data.remaining();
  if (len < off) {
    return false;
  }
  int state = 0;
  for (int i = off; i < len; ++i) {
    state = utf8d[256 + (state << 4) + utf8d[(0xff & data.get(i))]];
    if (state == 1) {
      return false;
    }
  }
  return true;
}

